block.script:
hold := 0
if ((#Entrance #ContactSensor).contactSensor_contact == false) {
hold = hold + 1
    if (hold >= 60) {
(#Hallway #Speaker).speaker_speak("Please close the front door")
        break
}
}
else {
hold = 0
}

n := 0
if (n >= 4) {
break
}
if ((#LivingRoom #Window).contactSensor_contact == false) {
(#LivingRoom #Speaker).speaker_speak("Please close the window")
}
n = n + 1

hold := 0
fired := false
if ((#LivingRoom #MotionSensor).motionSensor_motion == false) {
if (fired == false) {
hold = hold + 1
        if (hold >= 120) {
(#LivingRoom #Light).switch_off()
            fired = true
}
}
}
else {
hold = 0
    fired = false
}

triggered := false
if ((#LivingRoom #TemperatureSensor).temperatureSensor_temperature > 28) {
if (triggered == false) {
(#LivingRoom #Plug).switch_on()
        triggered = true
}
}
else {
triggered = false
}

t1 = (#WineCellar #TemperatureSensor).temperatureSensor_temperature
delay(10 MIN)
t2 = (#WineCellar #TemperatureSensor).temperatureSensor_temperature
if (t2 - t1 >= 2) {
(#WineCellar #AirConditioner).airConditioner_setTargetTemperature(t1)
}

n := 0
triggered := false
if ((#Mailbox #ContactSensor).contactSensor_contact == false) {
if (triggered == false) {
(#Kitchen #Speaker).speaker_speak("Mail has arrived")
        triggered = true
        n = n + 1
        if (n >= 3) {
break
}
}
}
else {
triggered = false
}

t := 0
if ((#Entrance #ContactSensor).contactSensor_contact == false) {
t = t + 1
    if (t == 180) {
(#Hallway #Speaker).speaker_speak("The front door is still open")
}
}
else {
t = 0
}

triggered := false
if ((#Entrance #MotionSensor).motionSensor_motion == true) {
if (triggered == false) {
(#Entrance #Light).switch_on()
        delay(1 MIN)
(#Entrance #Light).switch_off()
        triggered = true
}
}
else {
triggered = false
}

triggered := false
if ((#Entrance #ContactSensor).contactSensor_contact == false) {
if (triggered == false) {
vol = (#LivingRoom #Speaker).speaker_volume
        (#LivingRoom #Speaker).speaker_setVolume(10)
        delay(2 MIN)
(#LivingRoom #Speaker).speaker_setVolume(vol)
        triggered = true
}
}
else {
triggered = false
}

n := 0
hold := 0
fired := false
if ((#Entrance #ContactSensor).contactSensor_contact == false) {
if (fired == false) {
hold = hold + 1
        if (hold >= 60) {
(#Hallway #Speaker).speaker_speak("Please close the door")
            fired = true
            n = n + 1
            if (n >= 3) {
break
}
}
}
}
else {
hold = 0
    fired = false
}

wait until((#Entrance #ContactSensor).contactSensor_contact == false)
delay(1 MIN)
if ((#Entrance #ContactSensor).contactSensor_contact == false) {
(#Hallway #Speaker).speaker_speak("Please close the front door")
}

triggered := false
vol := (#LivingRoom #Speaker).speaker_volume
if ((#Entrance #ContactSensor).contactSensor_contact == false) {
if (triggered == false) {
(#LivingRoom #Speaker).speaker_setVolume(10)
        delay(2 MIN)
(#LivingRoom #Speaker).speaker_setVolume(vol)
        triggered = true
}
}
else {
triggered = false
}

hold := 0
if ((#LivingRoom #MotionSensor).motionSensor_motion == false) {
hold = hold + 1
    if (hold >= 120) {
(#LivingRoom #Light).switch_off()
}
}
else {
hold = 0
}

n := 0
if (n > 4) {
break
}
if ((#LivingRoom #Window).contactSensor_contact == false) {
(#LivingRoom #Speaker).speaker_speak("Please close the window")
}
n = n + 1
